import re

def entities(doc, scope) -> list:
    """
    Every distinct entity that appears in the scope, with its full human-readable description.
    """
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node.get('title') == f"{scope}: Objects":
            lines = node.get('lines', [])
            res = []
            for line in lines:
                # Example: 'Object 0: brown metal sphere (color=brown, material=metal, shape=sphere)'
                match = re.search(r"(Object \d+): (.*?) \(", line)
                if match:
                    res.append({"id": match.group(1), "description": match.group(2)})
            return res
    return []

def recorded_end(doc, scope) -> float:
    """
    The last time point covered by the scope's records (in the document's own time unit).
    """
    nodes = scope_nodes(doc, scope)
    max_f = 0.0
    for node in nodes:
        # Check Events list for frame numbers
        if node.get('title') == f"{scope}: Events":
            for line in node.get('lines', []):
                match = re.search(r"Frame (\d+):", line)
                if match:
                    max_f = max(max_f, float(match.group(1)))
        # Check Motion log table for frame numbers
        elif node.get('title') == f"{scope}: Motion log":
            table = node.get('table', {})
            for row in table.get('rows', []):
                if row and len(row) > 0:
                    try:
                        max_f = max(max_f, float(row[0]))
                    except (ValueError, TypeError):
                        continue
    return max_f

def observed_events(doc, scope) -> list:
    """
    Every interaction event (an event involving two or more entities) recorded for the scope.
    """
    nodes = scope_nodes(doc, scope)
    res = []
    for node in nodes:
        if node.get('title') == f"{scope}: Events":
            for line in node.get('lines', []):
                # Interaction events in CLEVRER are collisions:
                # 'Frame 24: Object 0 (brown metal sphere) collides with Object 1 (cyan rubber sphere).'
                match = re.search(r"Frame (\d+): (Object \d+) \(.*?\) collides with (Object \d+) \(.*?\)\.", line)
                if match:
                    res.append({
                        "time": float(match.group(1)),
                        "kind": "collides",
                        "participants": [match.group(2), match.group(3)]
                    })
            return res
    return []



