import numpy as np
import collections

def simulate(doc, scope, removed=(), horizon=None, start=0.0) -> list:
    """
    A forward model of the process recorded in the scope, run from time `start` to `horizon`.
    Incorporates friction (speed loss) and semi-elastic collisions.
    """
    def get_motion_log(doc, scope):
        nodes = scope_nodes(doc, scope)
        for node in nodes:
            if node.get('title') == f"{scope}: Motion log":
                table = node.get('table', {})
                cols = table.get('columns', [])
                rows = table.get('rows', [])
                col_idx = {name: i for i, name in enumerate(cols)}
                data = []
                for row in rows:
                    entry = {name: row[i] for name, i in col_idx.items()}
                    data.append(entry)
                return data
        return []

    # Constants estimated from data analysis
    FRICTION_LOSS = 0.0073  # Speed loss per frame
    COLLISION_DIST = 0.42    # Typical distance at collision
    RESTITUTION_COEFF = 0.36 # Average elasticity e

    ents = entities(doc, scope)
    ent_ids = [e['id'] for e in ents]
    logs_data = get_motion_log(doc, scope)

    obj_logs = collections.defaultdict(list)
    for entry in logs_data:
        oid = 'Object ' + entry['object'].split(' ')[0]
        obj_logs[oid].append({
            'f': float(entry['frame']),
            'x': float(entry['x']),
            'y': float(entry['y']),
            'vx': float(entry['vx']),
            'vy': float(entry['vy'])
        })

    for oid in obj_logs:
        obj_logs[oid].sort(key=lambda x: x['f'])

    states = {}
    entry_times = {}
    for oid in ent_ids:
        if oid in removed:
            continue
        recs = obj_logs.get(oid, [])
        if not recs:
            continue

        last_before = [r for r in recs if r['f'] <= start]
        if last_before:
            r = last_before[-1]
            dt_init = start - r['f']
            # Basic linear advance to start time
            states[oid] = {
                'x': r['x'] + r['vx'] * dt_init,
                'y': r['y'] + r['vy'] * dt_init,
                'vx': r['vx'],
                'vy': r['vy']
            }
            entry_times[oid] = start
        else:
            r = recs[0]
            states[oid] = {
                'x': r['x'],
                'y': r['y'],
                'vx': r['vx'],
                'vy': r['vy']
            }
            entry_times[oid] = r['f']

    if horizon is None:
        horizon = recorded_end(doc, scope)

    t = start
    dt = 0.1  # Time step
    events = []

    while t < horizon:
        current_active = [oid for oid, et in entry_times.items() if et <= t and oid not in removed]

        # 1. Update positions and apply friction
        for oid in current_active:
            s = states[oid]
            # Update position
            s['x'] += s['vx'] * dt
            s['y'] += s['vy'] * dt

            # Apply friction (constant speed loss)
            speed = np.sqrt(s['vx']**2 + s['vy']**2)
            if speed > 0.1:
                loss = FRICTION_LOSS * dt
                reduction = max(0, speed - loss) / speed
                s['vx'] *= reduction
                s['vy'] *= reduction
            else:
                s['vx'], s['vy'] = 0.0, 0.0

        # 2. Detect and resolve collisions
        for i in range(len(current_active)):
            for j in range(i + 1, len(current_active)):
                oid1, oid2 = current_active[i], current_active[j]
                s1, s2 = states[oid1], states[oid2]

                dx, dy = s1['x'] - s2['x'], s1['y'] - s2['y']
                dist_sq = dx*dx + dy*dy

                if dist_sq < COLLISION_DIST**2:
                    # Relative velocity
                    dvx, dvy = s1['vx'] - s2['vx'], s1['vy'] - s2['vy']
                    # Normal vector n = (x1-x2)/dist
                    dist = np.sqrt(dist_sq)
                    nx, ny = dx / dist, dy / dist

                    v_rel_n = dvx * nx + dvy * ny

                    # Collide only if moving toward each other
                    if v_rel_n < 0:
                        # Impulse scalar for equal masses
                        # J = -(1+e)*v_rel_n / (1/m + 1/m) = -m(1+e)v_rel_n / 2
                        # DeltaV = J/m * n = -(1+e)v_rel_n / 2 * n
                        impulse = -(1.0 + RESTITUTION_COEFF) * v_rel_n / 2.0

                        s1['vx'] += impulse * nx
                        s1['vy'] += impulse * ny
                        s2['vx'] -= impulse * nx
                        s2['vy'] -= impulse * ny

                        events.append({
                            "time": t,
                            "kind": "collides",
                            "participants": [oid1, oid2]
                        })
        t += dt

    return [e for e in events if e['time'] > start]

