    # 1. Estimated Constants from data analysis
    C = 0.0280  # Scaling factor: dx = v * dt * C
    K = 0.0180  # Friction factor: v_{t+1} = v_t * (1 - K)
    COLLISION_DIST = 0.42  # Average collision distance recorded
    MASS_MAP = {"metal": 2.0, "rubber": 1.0}

    # 2. Gather entity information and their materials
    ents_info = entities(doc, scope)
    ent_id_to_material = {}
    for e in ents_info:
        material = "metal" if "metal" in e['description'] else "rubber"
        ent_id_to_material[e['id']] = material

    # 3. Extract motion logs and identify when objects appear
    nodes = scope_nodes(doc, scope)
    motion_log_node = next((n for n in nodes if n.get('title') == f"{scope}: Motion log"), None)
    if not motion_log_node:
        return []

    rows = motion_log_node.get('table', {}).get('rows', [])

    # Map "Object X" -> "X color material shape"
    obj_map = {}
    for e in ents_info:
        idx = e['id'].split(' ')[1]
        obj_map[e['id']] = f"{idx} {e['description']}"

    # Group logs by object: obj_id -> sorted list of (frame, x, y, vx, vy)
    obj_logs = collections.defaultdict(list)
    for row in rows:
        if not row or len(row) < 6: continue
        frame = float(row[0])
        name = row[1]
        oid = next((k for k, v in obj_map.items() if v == name), None)
        if oid:
            obj_logs[oid].append((frame, float(row[2]), float(row[3]), float(row[4]), float(row[5])))

    for oid in obj_logs:
        obj_logs[oid].sort()

    # 4. Initialize state at 'start'
    current_state = {}
    for oid in obj_logs:
        if oid in removed:
            continue
        logs = obj_logs[oid]
        first_frame = logs[0][0]

        if first_frame > start:
            # Entity enters the scene at the time of its first record
            current_state[oid] = {
                'pos': np.array([logs[0][1], logs[0][2]]),
                'vel': np.array([logs[0][3], logs[0][4]]),
                'active': False,
                'entry': first_frame
            }
        else:
            # Find the record closest to start (at or before start)
            latest_rec = None
            for rec in logs:
                if rec[0] <= start:
                    latest_rec = rec
                else:
                    break

            if latest_rec:
                f_rec, x, y, vx, vy = latest_rec
                dt_offset = start - f_rec
                # Advance to start
                pos = np.array([x, y]) + np.array([vx, vy]) * dt_offset * C
                vel = np.array([vx, vy]) * ((1 - K) ** dt_offset)
                current_state[oid] = {
                    'pos': pos,
                    'vel': vel,
                    'active': True,
                    'entry': first_frame
                }
            else:
                current_state[oid] = {
                    'pos': np.array([logs[0][1], logs[0][2]]),
                    'vel': np.array([logs[0][3], logs[0][4]]),
                    'active': False,
                    'entry': first_frame
                }

    if horizon is None:
        horizon = recorded_end(doc, scope)

    # 5. Simulation Loop
    t = start
    events = []
    dt = 1.0
    collision_cooldown = collections.defaultdict(float)

    while t < horizon:
        t += dt

        # Activate objects entering the scene
        for oid, state in current_state.items():
            if not state['active'] and state['entry'] <= t:
                state['active'] = True

        active_objs = [oid for oid, state in current_state.items() if state['active']]

        # Update positions and velocities
        for oid in active_objs:
            state = current_state[oid]
            state['pos'] += state['vel'] * dt * C
            state['vel'] *= (1 - K) ** dt

        # Detect interactions
        for i in range(len(active_objs)):
            for j in range(i + 1, len(active_objs)):
                oid1, oid2 = active_objs[i], active_objs[j]

                if t < collision_cooldown[tuple(sorted((oid1, oid2)))]:
                    continue

                p1, p2 = current_state[oid1]['pos'], current_state[oid2]['pos']
                dist = np.linalg.norm(p1 - p2)

                if dist < COLLISION_DIST:
                    events.append({
                        "time": t,
                        "kind": "collides",
                        "participants": sorted([oid1, oid2])
                    })

                    # Simple elastic collision physics
                    v1, v2 = current_state[oid1]['vel'], current_state[oid2]['vel']
                    m1 = MASS_MAP.get(ent_id_to_material.get(oid1, "rubber"), 1.0)
                    m2 = MASS_MAP.get(ent_id_to_material.get(oid2, "rubber"), 1.0)

                    n = (p1 - p2) / (dist if dist > 1e-5 else 1.0)
                    v_rel = v1 - v2
                    vn = np.dot(v_rel, n)

                    if vn < 0:
                        impulse = (2 * m1 * m2 * vn) / (m1 + m2)
                        current_state[oid1]['vel'] -= (impulse / m1) * n
                        current_state[oid2]['vel'] += (impulse / m2) * n

                    collision_cooldown[tuple(sorted((oid1, oid2)))] = t + 5.0

    return events
